using System.Text;using System.Text.Json;using System.Text.Json.Serialization;
namespace QualityReporter.CSharp.Reporting;
public static class ReportWriter { static readonly JsonSerializerOptions Json=new(){WriteIndented=true,PropertyNamingPolicy=JsonNamingPolicy.CamelCase,DefaultIgnoreCondition=JsonIgnoreCondition.WhenWritingNull};public static void WriteJson(Report r,string path){Directory.CreateDirectory(Path.GetDirectoryName(Path.GetFullPath(path))!);File.WriteAllText(path,JsonSerializer.Serialize(r,Json));}public static Report Read(string path)=>JsonSerializer.Deserialize<Report>(File.ReadAllText(path),Json)!;public static void WriteMarkdown(Report r,string path){var b=new StringBuilder("# Quality Report — C#\n\n");var overall=r.Files.Count==0?0:r.Files.Average(x=>x.Risk.Score);b.AppendLine($"Overall Risk: {overall:F1} / 100\n");b.AppendLine("## Summary\n\n| Metric | Value |\n|---|---:|").AppendLine($"| Files | {r.Files.Count} |").AppendLine($"| Critical | {r.Files.Count(x=>x.Risk.Level=="critical")} |").AppendLine($"| Hotspots | {r.Files.Count(x=>x.Risk.Score>=60)} |");if(r.Warnings.Count>0)b.AppendLine("\n## Warnings\n").AppendJoin('\n',r.Warnings.Select(x=>$"- {x}"));b.AppendLine("\n\n## Top Hotspots\n\n| File | Risk | Changes | Rework | Complexity | Coverage |\n|---|---:|---:|---:|---:|---:|");foreach(var f in r.Files.Where(x=>x.Risk.Score>=60).OrderByDescending(x=>x.Risk.Score).Take(20))b.AppendLine($"| {f.Path} | {f.Risk.Score:F1} | {f.History.CommitCount} | {f.History.ReworkRate:P0} | {f.Metrics.Complexity} | {(f.Metrics.LineCoverage is double c?$"{c:F1}%":"Not Available")} |");b.AppendLine("\n## Change Coupling\n\n| File | Coupled With | Ratio |\n|---|---|---:|");foreach(var c in r.Files.SelectMany(x=>x.Couplings).OrderByDescending(x=>x.Ratio).Take(20))b.AppendLine($"| {c.File} | {c.CoupledWith} | {c.Ratio:P0} |");b.AppendLine("\n## High Complexity Functions\n\n| File | Function | Complexity |\n|---|---|---:|");foreach(var x in r.Files.SelectMany(f=>f.Functions.Select(fn=>(f.Path,fn))).OrderByDescending(x=>x.fn.Complexity).Take(20))b.AppendLine($"| {x.Path} | {x.fn.Name} | {x.fn.Complexity} |");Directory.CreateDirectory(Path.GetDirectoryName(Path.GetFullPath(path))!);File.WriteAllText(path,b.ToString());}}
